    BackupJob.add_member(:backup_job_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BackupJobId', traits: {"smithy.api#documentation" => "<p>Uniquely identifies a request to Backup to back up a resource.</p>"}))
    BackupJob.add_member(:backup_vault_name, Smithy::Schema::Shapes::ShapeRef.new(shape: BackupVaultName, location_name: 'BackupVaultName', traits: {"smithy.api#documentation" => "<p>The name of a logical container where backups are stored. Backup vaults are identified\n         by names that are unique to the account used to create them and the Amazon Web Services\n         Region where they are created.</p>"}))
    BackupJob.add_member(:backup_vault_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ARN, location_name: 'BackupVaultArn', traits: {"smithy.api#documentation" => "<p>An Amazon Resource Name (ARN) that uniquely identifies a backup vault; for example,\n         <code>arn:aws:backup:us-east-1:123456789012:backup-vault:aBackupVault</code>.</p>"}))
    BackupJob.add_member(:recovery_point_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ARN, location_name: 'RecoveryPointArn', traits: {"smithy.api#documentation" => "<p>An ARN that uniquely identifies a recovery point; for example,\n            <code>arn:aws:backup:us-east-1:123456789012:recovery-point:1EB3B5E7-9EB0-435A-A80B-108B488B0D45</code>.</p>"}))
    BackupJob.add_member(:resource_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ARN, location_name: 'ResourceArn', traits: {"smithy.api#documentation" => "<p>An ARN that uniquely identifies a resource. The format of the ARN depends on the\n         resource type.</p>"}))
    BackupJob.add_member(:creation_date, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CreationDate', traits: {"smithy.api#documentation" => "<p>The date and time a backup job is created, in Unix format and Coordinated Universal Time\n         (UTC). The value of <code>CreationDate</code> is accurate to milliseconds. For example, the\n         value 1516925490.087 represents Friday, January 26, 2018 12:11:30.087 AM.</p>"}))
    BackupJob.add_member(:completion_date, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CompletionDate', traits: {"smithy.api#documentation" => "<p>The date and time a job to create a backup job is completed, in Unix format and\n         Coordinated Universal Time (UTC). The value of <code>CompletionDate</code> is accurate to\n         milliseconds. For example, the value 1516925490.087 represents Friday, January 26, 2018\n         12:11:30.087 AM.</p>"}))
    BackupJob.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: BackupJobState, location_name: 'State', traits: {"smithy.api#documentation" => "<p>The current state of a backup job.</p>"}))
    BackupJob.add_member(:status_message, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StatusMessage', traits: {"smithy.api#documentation" => "<p>A detailed message explaining the status of the job to back up a resource.</p>"}))
    BackupJob.add_member(:percent_done, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PercentDone', traits: {"smithy.api#documentation" => "<p>Contains an estimated percentage complete of a job at the time the job status was\n         queried.</p>"}))
    BackupJob.add_member(:backup_size_in_bytes, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'BackupSizeInBytes', traits: {"smithy.api#documentation" => "<p>The size, in bytes, of a backup (recovery point).</p>\n         <p>This value can render differently depending on the resource type as Backup pulls in data information from other Amazon Web Services services. For example, the \n         value returned may show a value of <code>0</code>, which may differ from the \n         anticipated value.</p>\n         <p>The expected behavior for values by resource type are described as follows:</p>\n         <ul>\n            <li>\n               <p>Amazon Aurora, Amazon DocumentDB, and Amazon Neptune do\n               not have this value populate from the operation\n               <code>GetBackupJobStatus</code>.</p>\n            </li>\n            <li>\n               <p>For Amazon DynamoDB with advanced features, this value refers to the size\n               of the recovery point (backup).</p>\n            </li>\n            <li>\n               <p>Amazon EC2 and Amazon EBS show volume size (provisioned storage)\n               returned as part of this value. Amazon EBS does not return backup size\n               information; snapshot size will have the same value as the original resource that was\n               backed up.</p>\n            </li>\n            <li>\n               <p>For Amazon EFS, this value refers to the delta bytes transferred during a\n               backup.</p>\n            </li>\n            <li>\n               <p>Amazon FSx does not populate this value from the operation\n               <code>GetBackupJobStatus</code> for FSx file systems.</p>\n            </li>\n            <li>\n               <p>An Amazon RDS instance will show as <code>0</code>.</p>\n            </li>\n            <li>\n               <p>For virtual machines running VMware, this value is passed to Backup\n               through an asynchronous workflow, which can mean this displayed value can\n               under-represent the actual backup size.</p>\n            </li>\n         </ul>"}))
    BackupJob.add_member(:iam_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: IAMRoleArn, location_name: 'IamRoleArn', traits: {"smithy.api#documentation" => "<p>Specifies the IAM role ARN used to create the target recovery point. IAM roles other\n         than the default role must include either <code>AWSBackup</code> or <code>AwsBackup</code>\n         in the role name. For example,\n            <code>arn:aws:iam::123456789012:role/AWSBackupRDSAccess</code>. Role names without those\n         strings lack permissions to perform backup jobs.</p>"}))
    BackupJob.add_member(:created_by, Smithy::Schema::Shapes::ShapeRef.new(shape: RecoveryPointCreator, location_name: 'CreatedBy', traits: {"smithy.api#documentation" => "<p>Contains identifying information about the creation of a backup job, including the\n            <code>BackupPlanArn</code>, <code>BackupPlanId</code>, <code>BackupPlanVersion</code>,\n         and <code>BackupRuleId</code> of the backup plan used to create it.</p>"}))
    BackupJob.add_member(:expected_completion_date, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'ExpectedCompletionDate', traits: {"smithy.api#documentation" => "<p>The date and time a job to back up resources is expected to be completed, in Unix format\n         and Coordinated Universal Time (UTC). The value of <code>ExpectedCompletionDate</code> is\n         accurate to milliseconds. For example, the value 1516925490.087 represents Friday, January\n         26, 2018 12:11:30.087 AM.</p>"}))
    BackupJob.add_member(:start_by, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'StartBy', traits: {"smithy.api#documentation" => "<p>Specifies the time in Unix format and Coordinated Universal Time (UTC) when a backup job\n         must be started before it is canceled. The value is calculated by adding the start window\n         to the scheduled time. So if the scheduled time were 6:00 PM and the start window is 2\n         hours, the <code>StartBy</code> time would be 8:00 PM on the date specified. The value of\n            <code>StartBy</code> is accurate to milliseconds. For example, the value 1516925490.087\n         represents Friday, January 26, 2018 12:11:30.087 AM.</p>"}))
    BackupJob.add_member(:resource_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceType, location_name: 'ResourceType', traits: {"smithy.api#documentation" => "<p>The type of Amazon Web Services resource to be backed up; for example, an Amazon Elastic Block Store (Amazon EBS) volume or an Amazon Relational Database Service (Amazon RDS) database. For Windows Volume Shadow Copy Service (VSS) backups, the only\n         supported resource type is Amazon EC2.</p>"}))
    BackupJob.add_member(:bytes_transferred, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'BytesTransferred', traits: {"smithy.api#documentation" => "<p>The size in bytes transferred to a backup vault at the time that the job status was\n         queried.</p>"}))
    BackupJob.add_member(:backup_options, Smithy::Schema::Shapes::ShapeRef.new(shape: BackupOptions, location_name: 'BackupOptions', traits: {"smithy.api#documentation" => "<p>Specifies the backup option for a selected resource. This option is only available for\n         Windows Volume Shadow Copy Service (VSS) backup jobs.</p>\n         <p>Valid values: Set to <code>\"WindowsVSS\":\"enabled\"</code> to enable the\n            <code>WindowsVSS</code> backup option and create a Windows VSS backup. Set to\n            <code>\"WindowsVSS\":\"disabled\"</code> to create a regular backup. If you specify an\n         invalid option, you get an <code>InvalidParameterValueException</code> exception.</p>"}))
    BackupJob.add_member(:backup_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BackupType', traits: {"smithy.api#documentation" => "<p>Represents the type of backup for a backup job.</p>"}))
    BackupJob.add_member(:parent_job_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ParentJobId', traits: {"smithy.api#documentation" => "<p>This uniquely identifies a request to Backup \n         to back up a resource. The return will be the \n         parent (composite) job ID.</p>"}))
    BackupJob.add_member(:is_parent, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean2, location_name: 'IsParent', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>This is a boolean value indicating this is \n         a parent (composite) backup job.</p>"}))
    BackupJob.add_member(:resource_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ResourceName', traits: {"smithy.api#documentation" => "<p>The non-unique name of the resource that \n         belongs to the specified backup.</p>"}))
    BackupJob.add_member(:initiation_date, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'InitiationDate', traits: {"smithy.api#documentation" => "<p>The date on which the backup \n         job was initiated.</p>"}))
    BackupJob.add_member(:message_category, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MessageCategory', traits: {"smithy.api#documentation" => "<p>This parameter is the job count for the specified \n         message category.</p>\n         <p>Example strings may include <code>AccessDenied</code>, \n      <code>SUCCESS</code>, <code>AGGREGATE_ALL</code>, and \n      <code>INVALIDPARAMETERS</code>. See \n         <a href=\"https://docs.aws.amazon.com/aws-backup/latest/devguide/monitoring.html\">Monitoring</a> \n         for a list of MessageCategory strings.</p>\n         <p>The the value ANY returns count of all message categories.</p>\n         <p>\n            <code>AGGREGATE_ALL</code> aggregates job counts \n         for all message categories and returns the sum.</p>"}))
