    BackupRule.add_member(:rule_name, Smithy::Schema::Shapes::ShapeRef.new(shape: BackupRuleName, location_name: 'RuleName', traits: {"smithy.api#documentation" => "<p>A display name for a backup rule. Must contain 1 to 50 alphanumeric or '-_.'\n         characters.</p>", "smithy.api#required" => {}}))
    BackupRule.add_member(:target_backup_vault_name, Smithy::Schema::Shapes::ShapeRef.new(shape: BackupVaultName, location_name: 'TargetBackupVaultName', traits: {"smithy.api#documentation" => "<p>The name of a logical container where backups are stored. Backup vaults are identified\n         by names that are unique to the account used to create them and the Amazon Web Services\n         Region where they are created.</p>", "smithy.api#required" => {}}))
    BackupRule.add_member(:schedule_expression, Smithy::Schema::Shapes::ShapeRef.new(shape: CronExpression, location_name: 'ScheduleExpression', traits: {"smithy.api#documentation" => "<p>A cron expression in UTC specifying when Backup initiates a backup job. \n         When no CRON expression is provided, Backup will use the default \n         expression <code>cron(0 5 ? * * *)</code>.</p>\n         <p>For more information about Amazon Web Services cron expressions, see <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/events/ScheduledEvents.html\">Schedule Expressions for Rules</a> in the <i>Amazon CloudWatch Events User\n            Guide</i>.</p>\n         <p>Two examples of Amazon Web Services cron expressions are <code> 15 * ? * * *</code> (take\n         a backup every hour at 15 minutes past the hour) and <code>0 12 * * ? *</code> (take a\n         backup every day at 12 noon UTC).</p>\n         <p>For a table of examples, click the preceding link and scroll down the page.</p>"}))
    BackupRule.add_member(:start_window_minutes, Smithy::Schema::Shapes::ShapeRef.new(shape: WindowMinutes, location_name: 'StartWindowMinutes', traits: {"smithy.api#documentation" => "<p>A value in minutes after a backup is scheduled before a job will be canceled if it\n         doesn't start successfully. This value is optional. \n         If this value is included, it must be at least 60 minutes to avoid errors.</p>\n         <p>During the start window, the backup job status remains in <code>CREATED</code> status until it \n         has successfully begun or until the start window time has run out. If within the start \n         window time Backup receives an error that allows the job to be retried, \n         Backup will automatically retry to begin the job at least every 10 minutes \n         until the backup \n         successfully begins (the job status changes to <code>RUNNING</code>) or until the job status \n         changes to <code>EXPIRED</code> (which is expected to occur when the start window time is over).</p>"}))
    BackupRule.add_member(:completion_window_minutes, Smithy::Schema::Shapes::ShapeRef.new(shape: WindowMinutes, location_name: 'CompletionWindowMinutes', traits: {"smithy.api#documentation" => "<p>A value in minutes after a backup job is successfully started before it must be\n         completed or it will be canceled by Backup. This value is optional.</p>"}))
    BackupRule.add_member(:lifecycle, Smithy::Schema::Shapes::ShapeRef.new(shape: Lifecycle, location_name: 'Lifecycle', traits: {"smithy.api#documentation" => "<p>The lifecycle defines when a protected resource is transitioned to cold storage and when\n         it expires. Backup transitions and expires backups automatically according to\n         the lifecycle that you define. </p>\n         <p>Backups transitioned to cold storage must be stored in cold storage for a minimum of 90\n         days. Therefore, the “retention” setting must be 90 days greater than the “transition to\n         cold after days” setting. The “transition to cold after days” setting cannot be changed\n         after a backup has been transitioned to cold. </p>\n         <p>Resource types that can transition to cold storage are listed in the <a href=\"https://docs.aws.amazon.com/aws-backup/latest/devguide/backup-feature-availability.html#features-by-resource\">Feature availability \n         by resource</a> table. Backup ignores this expression for other resource types.</p>"}))
    BackupRule.add_member(:recovery_point_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'RecoveryPointTags', traits: {"smithy.api#documentation" => "<p>The tags that are assigned to resources that are associated\n         with this rule when restored from backup.</p>"}))
    BackupRule.add_member(:rule_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'RuleId', traits: {"smithy.api#documentation" => "<p>Uniquely identifies a rule that is used to schedule the backup of a selection of\n         resources.</p>"}))
    BackupRule.add_member(:copy_actions, Smithy::Schema::Shapes::ShapeRef.new(shape: CopyActions, location_name: 'CopyActions', traits: {"smithy.api#documentation" => "<p>An array of <code>CopyAction</code> objects, which contains the details of the copy\n         operation.</p>"}))
    BackupRule.add_member(:enable_continuous_backup, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'EnableContinuousBackup', traits: {"smithy.api#documentation" => "<p>Specifies whether Backup creates continuous backups. True causes Backup to create continuous backups capable of point-in-time restore (PITR). False\n         (or not specified) causes Backup to create snapshot backups.</p>"}))
    BackupRule.add_member(:schedule_expression_timezone, Smithy::Schema::Shapes::ShapeRef.new(shape: Timezone, location_name: 'ScheduleExpressionTimezone', traits: {"smithy.api#documentation" => "<p>The timezone in which the schedule expression is set. By default, \n         ScheduleExpressions are in UTC. You can modify this to a specified timezone.</p>"}))
    BackupRule.add_member(:index_actions, Smithy::Schema::Shapes::ShapeRef.new(shape: IndexActions, location_name: 'IndexActions', traits: {"smithy.api#documentation" => "<p>IndexActions is an array you use to specify how backup data should \n         be indexed.</p>\n         <p>eEach BackupRule can have 0 or 1 IndexAction, as each backup can have up \n         to one index associated with it.</p>\n         <p>Within the array is ResourceType. Only one will be accepted for each BackupRule.</p>"}))
