    BackupRuleInput.add_member(:start_window_minutes, Smithy::Schema::Shapes::ShapeRef.new(shape: WindowMinutes, location_name: 'StartWindowMinutes', traits: {"smithy.api#documentation" => "<p>A value in minutes after a backup is scheduled before a job will be canceled if it\n         doesn't start successfully. This value is optional. \n         If this value is included, it must be at least 60 minutes to avoid errors.</p>\n         <p>This parameter has a maximum value of 100 years (52,560,000 minutes).</p>\n         <p>During the start window, the backup job status remains in <code>CREATED</code> status until it \n         has successfully begun or until the start window time has run out. If within the start \n         window time Backup receives an error that allows the job to be retried, \n         Backup will automatically retry to begin the job at least every 10 minutes \n         until the backup \n         successfully begins (the job status changes to <code>RUNNING</code>) or until the job status \n         changes to <code>EXPIRED</code> (which is expected to occur when the start window time is over).</p>"}))
    BackupRuleInput.add_member(:completion_window_minutes, Smithy::Schema::Shapes::ShapeRef.new(shape: WindowMinutes, location_name: 'CompletionWindowMinutes', traits: {"smithy.api#documentation" => "<p>A value in minutes after a backup job is successfully started before it must be\n         completed or it will be canceled by Backup. This value is optional.</p>"}))
    BackupRuleInput.add_member(:lifecycle, Smithy::Schema::Shapes::ShapeRef.new(shape: Lifecycle, location_name: 'Lifecycle', traits: {"smithy.api#documentation" => "<p>The lifecycle defines when a protected resource is transitioned to cold storage and when\n         it expires. Backup will transition and expire backups automatically according\n         to the lifecycle that you define. </p>\n         <p>Backups transitioned to cold storage must be stored in cold storage for a minimum of 90\n         days. Therefore, the “retention” setting must be 90 days greater than the “transition to\n         cold after days” setting. The “transition to cold after days” setting cannot be changed\n         after a backup has been transitioned to cold storage.</p>\n         <p>Resource types that can transition to cold storage are listed in the <a href=\"https://docs.aws.amazon.com/aws-backup/latest/devguide/backup-feature-availability.html#features-by-resource\">Feature availability \n         by resource</a> table. Backup ignores this expression for other resource types.</p>\n         <p>This parameter has a maximum value of 100 years (36,500 days).</p>"}))
    BackupRuleInput.add_member(:recovery_point_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'RecoveryPointTags', traits: {"smithy.api#documentation" => "<p>The tags to assign to the resources.</p>"}))
    BackupRuleInput.add_member(:copy_actions, Smithy::Schema::Shapes::ShapeRef.new(shape: CopyActions, location_name: 'CopyActions', traits: {"smithy.api#documentation" => "<p>An array of <code>CopyAction</code> objects, which contains the details of the copy\n         operation.</p>"}))
    BackupRuleInput.add_member(:enable_continuous_backup, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'EnableContinuousBackup', traits: {"smithy.api#documentation" => "<p>Specifies whether Backup creates continuous backups. True causes Backup to create continuous backups capable of point-in-time restore (PITR). False\n         (or not specified) causes Backup to create snapshot backups.</p>"}))
    BackupRuleInput.add_member(:schedule_expression_timezone, Smithy::Schema::Shapes::ShapeRef.new(shape: Timezone, location_name: 'ScheduleExpressionTimezone', traits: {"smithy.api#documentation" => "<p>The timezone in which the schedule expression is set. By default, \n         ScheduleExpressions are in UTC. You can modify this to a specified timezone.</p>"}))
    BackupRuleInput.add_member(:index_actions, Smithy::Schema::Shapes::ShapeRef.new(shape: IndexActions, location_name: 'IndexActions', traits: {"smithy.api#documentation" => "<p>There can up to one IndexAction in each BackupRule, as each backup \n         can have 0 or 1 backup index associated with it.</p>\n         <p>Within the array is ResourceTypes. Only 1 resource type will \n         be accepted for each BackupRule. Valid values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>EBS</code> for Amazon Elastic Block Store</p>\n            </li>\n            <li>\n               <p>\n                  <code>S3</code> for Amazon Simple Storage Service (Amazon S3)</p>\n            </li>\n         </ul>"}))
