    DescribeBackupJobOutput.add_member(:backup_size_in_bytes, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'BackupSizeInBytes', traits: {"smithy.api#documentation" => "<p>The size, in bytes, of a backup (recovery point).</p>\n         <p>This value can render differently depending on the resource type as Backup pulls in data information from other Amazon Web Services services. For example, the \n         value returned may show a value of <code>0</code>, which may differ from the \n         anticipated value.</p>\n         <p>The expected behavior for values by resource type are described as follows:</p>\n         <ul>\n            <li>\n               <p>Amazon Aurora, Amazon DocumentDB, and Amazon Neptune do\n               not have this value populate from the operation\n               <code>GetBackupJobStatus</code>.</p>\n            </li>\n            <li>\n               <p>For Amazon DynamoDB with advanced features, this value refers to the size\n               of the recovery point (backup).</p>\n            </li>\n            <li>\n               <p>Amazon EC2 and Amazon EBS show volume size (provisioned storage)\n               returned as part of this value. Amazon EBS does not return backup size\n               information; snapshot size will have the same value as the original resource that was\n               backed up.</p>\n            </li>\n            <li>\n               <p>For Amazon EFS, this value refers to the delta bytes transferred during a\n               backup.</p>\n            </li>\n            <li>\n               <p>Amazon FSx does not populate this value from the operation\n               <code>GetBackupJobStatus</code> for FSx file systems.</p>\n            </li>\n            <li>\n               <p>An Amazon RDS instance will show as <code>0</code>.</p>\n            </li>\n            <li>\n               <p>For virtual machines running VMware, this value is passed to Backup\n               through an asynchronous workflow, which can mean this displayed value can\n               under-represent the actual backup size.</p>\n            </li>\n         </ul>"}))
    DescribeBackupJobOutput.add_member(:iam_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: IAMRoleArn, location_name: 'IamRoleArn', traits: {"smithy.api#documentation" => "<p>Specifies the IAM role ARN used to create the target recovery point; for example,\n            <code>arn:aws:iam::123456789012:role/S3Access</code>.</p>"}))
    DescribeBackupJobOutput.add_member(:created_by, Smithy::Schema::Shapes::ShapeRef.new(shape: RecoveryPointCreator, location_name: 'CreatedBy', traits: {"smithy.api#documentation" => "<p>Contains identifying information about the creation of a backup job, including the\n            <code>BackupPlanArn</code>, <code>BackupPlanId</code>, <code>BackupPlanVersion</code>,\n         and <code>BackupRuleId</code> of the backup plan that is used to create it.</p>"}))
    DescribeBackupJobOutput.add_member(:resource_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceType, location_name: 'ResourceType', traits: {"smithy.api#documentation" => "<p>The type of Amazon Web Services resource to be backed up; for example, an Amazon Elastic Block Store (Amazon EBS) volume or an Amazon Relational Database Service (Amazon RDS) database.</p>"}))
    DescribeBackupJobOutput.add_member(:bytes_transferred, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'BytesTransferred', traits: {"smithy.api#documentation" => "<p>The size in bytes transferred to a backup vault at the time that the job status was\n         queried.</p>"}))
    DescribeBackupJobOutput.add_member(:expected_completion_date, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'ExpectedCompletionDate', traits: {"smithy.api#documentation" => "<p>The date and time that a job to back up resources is expected to be completed, in Unix\n         format and Coordinated Universal Time (UTC). The value of\n            <code>ExpectedCompletionDate</code> is accurate to milliseconds. For example, the value\n         1516925490.087 represents Friday, January 26, 2018 12:11:30.087 AM.</p>"}))
    DescribeBackupJobOutput.add_member(:start_by, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'StartBy', traits: {"smithy.api#documentation" => "<p>Specifies the time in Unix format and Coordinated Universal Time (UTC) when a backup job\n         must be started before it is canceled. The value is calculated by adding the start window\n         to the scheduled time. So if the scheduled time were 6:00 PM and the start window is 2\n         hours, the <code>StartBy</code> time would be 8:00 PM on the date specified. The value of\n            <code>StartBy</code> is accurate to milliseconds. For example, the value 1516925490.087\n         represents Friday, January 26, 2018 12:11:30.087 AM.</p>"}))
    DescribeBackupJobOutput.add_member(:backup_options, Smithy::Schema::Shapes::ShapeRef.new(shape: BackupOptions, location_name: 'BackupOptions', traits: {"smithy.api#documentation" => "<p>Represents the options specified as part of backup plan or on-demand backup job.</p>"}))
    DescribeBackupJobOutput.add_member(:backup_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BackupType', traits: {"smithy.api#documentation" => "<p>Represents the actual backup type selected for a backup job. For example, if a\n         successful Windows Volume Shadow Copy Service (VSS) backup was taken,\n            <code>BackupType</code> returns <code>\"WindowsVSS\"</code>. If <code>BackupType</code> is\n         empty, then the backup type was a regular backup.</p>"}))
    DescribeBackupJobOutput.add_member(:parent_job_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ParentJobId', traits: {"smithy.api#documentation" => "<p>This returns the parent (composite) resource backup job ID.</p>"}))
    DescribeBackupJobOutput.add_member(:is_parent, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean2, location_name: 'IsParent', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>This returns the boolean value that a backup job is a parent (composite) job.</p>"}))
    DescribeBackupJobOutput.add_member(:number_of_child_jobs, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'NumberOfChildJobs', traits: {"smithy.api#documentation" => "<p>This returns the number of child (nested) backup jobs.</p>"}))
    DescribeBackupJobOutput.add_member(:child_jobs_in_state, Smithy::Schema::Shapes::ShapeRef.new(shape: BackupJobChildJobsInState, location_name: 'ChildJobsInState', traits: {"smithy.api#documentation" => "<p>This returns the statistics of the included child (nested) backup jobs.</p>"}))
    DescribeBackupJobOutput.add_member(:resource_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ResourceName', traits: {"smithy.api#documentation" => "<p>The non-unique name of the resource that \n         belongs to the specified backup.</p>"}))
    DescribeBackupJobOutput.add_member(:initiation_date, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'InitiationDate', traits: {"smithy.api#documentation" => "<p>The date a backup job was initiated.</p>"}))
    DescribeBackupJobOutput.add_member(:message_category, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MessageCategory', traits: {"smithy.api#documentation" => "<p>The job count for the specified \n         message category.</p>\n         <p>Example strings may include <code>AccessDenied</code>, <code>SUCCESS</code>,\n            <code>AGGREGATE_ALL</code>, and <code>INVALIDPARAMETERS</code>. View <a href=\"https://docs.aws.amazon.com/aws-backup/latest/devguide/monitoring.html\">Monitoring</a>\n         for a list of accepted MessageCategory strings.</p>"}))
