    DescribeBackupVaultOutput.add_member(:backup_vault_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BackupVaultName', traits: {"smithy.api#documentation" => "<p>The name of a logical container where backups are stored. Backup vaults are identified\n         by names that are unique to the account used to create them and the Region where they are\n         created.</p>"}))
