    DescribeBackupVaultOutput.add_member(:vault_type, Smithy::Schema::Shapes::ShapeRef.new(shape: VaultType, location_name: 'VaultType', traits: {"smithy.api#documentation" => "<p>The type of vault described.</p>"}))
    DescribeBackupVaultOutput.add_member(:vault_state, Smithy::Schema::Shapes::ShapeRef.new(shape: VaultState, location_name: 'VaultState', traits: {"smithy.api#documentation" => "<p>The current state of the vault.-></p>"}))
    DescribeBackupVaultOutput.add_member(:encryption_key_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ARN, location_name: 'EncryptionKeyArn', traits: {"smithy.api#documentation" => "<p>The server-side encryption key that is used to protect your backups; for example,\n            <code>arn:aws:kms:us-west-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>.</p>"}))
    DescribeBackupVaultOutput.add_member(:creation_date, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CreationDate', traits: {"smithy.api#documentation" => "<p>The date and time that a backup vault is created, in Unix format and Coordinated\n         Universal Time (UTC). The value of <code>CreationDate</code> is accurate to milliseconds.\n         For example, the value 1516925490.087 represents Friday, January 26, 2018 12:11:30.087\n         AM.</p>"}))
    DescribeBackupVaultOutput.add_member(:creator_request_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CreatorRequestId', traits: {"smithy.api#documentation" => "<p>A unique string that identifies the request and allows failed requests to be retried\n         without the risk of running the operation twice. This parameter is optional. If used, this\n         parameter must contain 1 to 50 alphanumeric or '-_.' characters.</p>"}))
    DescribeBackupVaultOutput.add_member(:number_of_recovery_points, Smithy::Schema::Shapes::ShapeRef.new(shape: Long2, location_name: 'NumberOfRecoveryPoints', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The number of recovery points that are stored in a backup vault.</p>\n         <p>Recovery point count value displayed in the console can be an approximation. Use <a href=\"https://docs.aws.amazon.com/aws-backup/latest/devguide/API_ListRecoveryPointsByBackupVault.html\">\n               <code>ListRecoveryPointsByBackupVault</code>\n            </a> API to obtain the exact\n         count.</p>"}))
    DescribeBackupVaultOutput.add_member(:locked, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'Locked', traits: {"smithy.api#documentation" => "<p>A Boolean that indicates whether Backup Vault Lock is currently protecting\n         the backup vault. <code>True</code> means that Vault Lock causes delete or update\n         operations on the recovery points stored in the vault to fail.</p>"}))
    DescribeBackupVaultOutput.add_member(:min_retention_days, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'MinRetentionDays', traits: {"smithy.api#documentation" => "<p>The Backup Vault Lock setting that specifies the minimum retention period\n         that the vault retains its recovery points. If this\n         parameter is not specified, Vault Lock will not enforce a minimum retention period.</p>\n         <p>If specified, any backup or copy job to the vault must have a lifecycle policy with a\n         retention period equal to or longer than the minimum retention period. If the job's\n         retention period is shorter than that minimum retention period, then the vault fails the\n         backup or copy job, and you should either modify your lifecycle settings or use a different\n         vault. Recovery points already stored in the vault prior to Vault Lock are not\n         affected.</p>"}))
    DescribeBackupVaultOutput.add_member(:max_retention_days, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'MaxRetentionDays', traits: {"smithy.api#documentation" => "<p>The Backup Vault Lock setting that specifies the maximum retention period\n         that the vault retains its recovery points. If this parameter is not specified, Vault Lock\n         does not enforce a maximum retention period on the recovery points in the vault (allowing\n         indefinite storage).</p>\n         <p>If specified, any backup or copy job to the vault must have a lifecycle policy with a\n         retention period equal to or shorter than the maximum retention period. If the job's\n         retention period is longer than that maximum retention period, then the vault fails the\n         backup or copy job, and you should either modify your lifecycle settings or use a different\n         vault. Recovery points already stored in the vault prior to Vault Lock are not\n         affected.</p>"}))
    DescribeBackupVaultOutput.add_member(:lock_date, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'LockDate', traits: {"smithy.api#documentation" => "<p>The date and time when Backup Vault Lock configuration cannot be changed or\n         deleted.</p>\n         <p>If you applied Vault Lock to your vault without specifying a lock date, you can change\n         any of your Vault Lock settings, or delete Vault Lock from the vault entirely, at any\n         time.</p>\n         <p>This value is in Unix format, Coordinated Universal Time (UTC), and accurate to\n         milliseconds. For example, the value 1516925490.087 represents Friday, January 26, 2018\n         12:11:30.087 AM.</p>"}))
    DescribeBackupVaultOutput.add_member(:source_backup_vault_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ARN, location_name: 'SourceBackupVaultArn', traits: {"smithy.api#documentation" => "<p>The ARN of the source backup vault from which this restore access backup vault was created.</p>"}))
