    DescribeFrameworkOutput.add_member(:creation_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CreationTime', traits: {"smithy.api#documentation" => "<p>The date and time that a framework is created, in ISO 8601 representation. The value of <code>CreationTime</code> is accurate to milliseconds. For example,\n         2020-07-10T15:00:00.000-08:00 represents the 10th of July 2020 at 3:00 PM 8 hours behind\n         UTC.</p>"}))
    DescribeFrameworkOutput.add_member(:deployment_status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DeploymentStatus', traits: {"smithy.api#documentation" => "<p>The deployment status of a framework. The statuses are:</p>\n         <p>\n            <code>CREATE_IN_PROGRESS | UPDATE_IN_PROGRESS | DELETE_IN_PROGRESS | COMPLETED |\n            FAILED</code>\n         </p>"}))
    DescribeFrameworkOutput.add_member(:framework_status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'FrameworkStatus', traits: {"smithy.api#documentation" => "<p>A framework consists of one or more controls. Each control governs a resource, such as\n         backup plans, backup selections, backup vaults, or recovery points. You can also turn\n            Config recording on or off for each resource. The statuses are:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>ACTIVE</code> when recording is turned on for all resources governed by the\n               framework.</p>\n            </li>\n            <li>\n               <p>\n                  <code>PARTIALLY_ACTIVE</code> when recording is turned off for at least one\n               resource governed by the framework.</p>\n            </li>\n            <li>\n               <p>\n                  <code>INACTIVE</code> when recording is turned off for all resources governed by\n               the framework.</p>\n            </li>\n            <li>\n               <p>\n                  <code>UNAVAILABLE</code> when Backup is unable to validate recording\n               status at this time.</p>\n            </li>\n         </ul>"}))
    DescribeFrameworkOutput.add_member(:idempotency_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'IdempotencyToken', traits: {"smithy.api#documentation" => "<p>A customer-chosen string that you can use to distinguish between otherwise identical\n         calls to <code>DescribeFrameworkOutput</code>. Retrying a successful request with the same\n         idempotency token results in a success message with no action taken.</p>"}))
