    DescribeRecoveryPointOutput.add_member(:source_backup_vault_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ARN, location_name: 'SourceBackupVaultArn', traits: {"smithy.api#documentation" => "<p>An Amazon Resource Name (ARN) that uniquely identifies the source vault where the\n         resource was originally backed up in; for example,\n         <code>arn:aws:backup:us-east-1:123456789012:backup-vault:aBackupVault</code>. If the recovery is\n         restored to the same Amazon Web Services account or Region, this value will be\n            <code>null</code>.</p>"}))
    DescribeRecoveryPointOutput.add_member(:resource_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ARN, location_name: 'ResourceArn', traits: {"smithy.api#documentation" => "<p>An ARN that uniquely identifies a saved resource. The format of the ARN depends on the\n         resource type.</p>"}))
    DescribeRecoveryPointOutput.add_member(:resource_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceType, location_name: 'ResourceType', traits: {"smithy.api#documentation" => "<p>The type of Amazon Web Services resource to save as a recovery point; for example, an\n            Amazon Elastic Block Store (Amazon EBS) volume or an Amazon Relational Database Service (Amazon RDS) database.</p>"}))
    DescribeRecoveryPointOutput.add_member(:created_by, Smithy::Schema::Shapes::ShapeRef.new(shape: RecoveryPointCreator, location_name: 'CreatedBy', traits: {"smithy.api#documentation" => "<p>Contains identifying information about the creation of a recovery point, including the\n            <code>BackupPlanArn</code>, <code>BackupPlanId</code>, <code>BackupPlanVersion</code>,\n         and <code>BackupRuleId</code> of the backup plan used to create it.</p>"}))
    DescribeRecoveryPointOutput.add_member(:iam_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: IAMRoleArn, location_name: 'IamRoleArn', traits: {"smithy.api#documentation" => "<p>Specifies the IAM role ARN used to create the target recovery point; for example,\n            <code>arn:aws:iam::123456789012:role/S3Access</code>.</p>"}))
    DescribeRecoveryPointOutput.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: RecoveryPointStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>A status code specifying the state of the recovery point. For more information, see \n         <a href=\"https://docs.aws.amazon.com/aws-backup/latest/devguide/applicationstackbackups.html#cfnrecoverypointstatus\">\n            Recovery point status</a> in the <i>Backup Developer \n               Guide</i>.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>CREATING</code> status indicates that an Backup job has been \n               initiated for a resource. The backup process has started and is actively processing \n               a backup job for the associated recovery point.</p>\n            </li>\n            <li>\n               <p>\n                  <code>AVAILABLE</code> status indicates that the backup was successfully created \n               for the recovery point. The backup process has completed without any issues, and the \n               recovery point is now ready for use.</p>\n            </li>\n            <li>\n               <p>\n                  <code>PARTIAL</code> status indicates a composite recovery point has one or more \n               nested recovery points that were not in the backup.</p>\n            </li>\n            <li>\n               <p>\n                  <code>EXPIRED</code> status indicates that the recovery point has exceeded its retention\n               period, but Backup lacks permission or is otherwise unable to delete it. To\n               manually delete these recovery points, see <a href=\"https://docs.aws.amazon.com/aws-backup/latest/devguide/gs-cleanup-resources.html#cleanup-backups\"> Step 3:\n                  Delete the recovery points</a> in the <i>Clean up resources</i>\n               section of <i>Getting started</i>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>STOPPED</code> status occurs on a continuous backup where a user has taken some\n               action that causes the continuous backup to be disabled. This can be caused by the removal\n               of permissions, turning off versioning, turning off events being sent to EventBridge,\n               or disabling the EventBridge rules that are put in place by Backup. For\n               recovery points of Amazon S3, Amazon RDS, and Amazon Aurora\n               resources, this status occurs when the retention period of a continuous backup rule is\n               changed.</p>\n               <p>To resolve <code>STOPPED</code> status, ensure that all requested permissions are in\n               place and that versioning is enabled on the S3 bucket. Once these conditions are met, the\n               next instance of a backup rule running will result in a new continuous recovery point being\n               created. The recovery points with STOPPED status do not need to be deleted.</p>\n               <p>For SAP HANA on Amazon EC2\n               <code>STOPPED</code> status occurs due to user action, application misconfiguration, or\n               backup failure. To ensure that future continuous backups succeed, refer to the recovery\n               point status and check SAP HANA for details.</p>\n            </li>\n         </ul>"}))
    DescribeRecoveryPointOutput.add_member(:status_message, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StatusMessage', traits: {"smithy.api#documentation" => "<p>A status message explaining the status of the recovery point.</p>"}))
    DescribeRecoveryPointOutput.add_member(:creation_date, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CreationDate', traits: {"smithy.api#documentation" => "<p>The date and time that a recovery point is created, in Unix format and Coordinated\n         Universal Time (UTC). The value of <code>CreationDate</code> is accurate to milliseconds.\n         For example, the value 1516925490.087 represents Friday, January 26, 2018 12:11:30.087\n         AM.</p>"}))
    DescribeRecoveryPointOutput.add_member(:initiation_date, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'InitiationDate', traits: {"smithy.api#documentation" => "<p>The date and time when the backup job that created this recovery point was initiated, in\n         Unix format and Coordinated Universal Time (UTC).</p>"}))
    DescribeRecoveryPointOutput.add_member(:completion_date, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CompletionDate', traits: {"smithy.api#documentation" => "<p>The date and time that a job to create a recovery point is completed, in Unix format and\n         Coordinated Universal Time (UTC). The value of <code>CompletionDate</code> is accurate to\n         milliseconds. For example, the value 1516925490.087 represents Friday, January 26, 2018\n         12:11:30.087 AM.</p>"}))
    DescribeRecoveryPointOutput.add_member(:backup_size_in_bytes, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'BackupSizeInBytes', traits: {"smithy.api#documentation" => "<p>The size, in bytes, of a backup.</p>"}))
    DescribeRecoveryPointOutput.add_member(:calculated_lifecycle, Smithy::Schema::Shapes::ShapeRef.new(shape: CalculatedLifecycle, location_name: 'CalculatedLifecycle', traits: {"smithy.api#documentation" => "<p>A <code>CalculatedLifecycle</code> object containing <code>DeleteAt</code> and\n            <code>MoveToColdStorageAt</code> timestamps.</p>"}))
    DescribeRecoveryPointOutput.add_member(:lifecycle, Smithy::Schema::Shapes::ShapeRef.new(shape: Lifecycle, location_name: 'Lifecycle', traits: {"smithy.api#documentation" => "<p>The lifecycle defines when a protected resource is transitioned to cold storage and when\n         it expires. Backup transitions and expires backups automatically according to\n         the lifecycle that you define.</p>\n         <p>Backups that are transitioned to cold storage must be stored in cold storage for a\n         minimum of 90 days. Therefore, the “retention” setting must be 90 days greater than the\n         “transition to cold after days” setting. The “transition to cold after days” setting cannot\n         be changed after a backup has been transitioned to cold. </p>\n         <p>Resource types that can transition to cold storage are listed in the <a href=\"https://docs.aws.amazon.com/aws-backup/latest/devguide/backup-feature-availability.html#features-by-resource\">Feature \n         availability by resource</a> table. Backup ignores this expression for other resource types.</p>"}))
    DescribeRecoveryPointOutput.add_member(:encryption_key_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ARN, location_name: 'EncryptionKeyArn', traits: {"smithy.api#documentation" => "<p>The server-side encryption key used to protect your backups; for example,\n            <code>arn:aws:kms:us-west-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>.</p>"}))
    DescribeRecoveryPointOutput.add_member(:is_encrypted, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean2, location_name: 'IsEncrypted', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>A Boolean value that is returned as <code>TRUE</code> if the specified recovery point is\n         encrypted, or <code>FALSE</code> if the recovery point is not encrypted.</p>"}))
    DescribeRecoveryPointOutput.add_member(:storage_class, Smithy::Schema::Shapes::ShapeRef.new(shape: StorageClass, location_name: 'StorageClass', traits: {"smithy.api#documentation" => "<p>Specifies the storage class of the recovery point. Valid values are <code>WARM</code> or\n            <code>COLD</code>.</p>"}))
    DescribeRecoveryPointOutput.add_member(:last_restore_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'LastRestoreTime', traits: {"smithy.api#documentation" => "<p>The date and time that a recovery point was last restored, in Unix format and\n         Coordinated Universal Time (UTC). The value of <code>LastRestoreTime</code> is accurate to\n         milliseconds. For example, the value 1516925490.087 represents Friday, January 26, 2018\n         12:11:30.087 AM.</p>"}))
    DescribeRecoveryPointOutput.add_member(:parent_recovery_point_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ARN, location_name: 'ParentRecoveryPointArn', traits: {"smithy.api#documentation" => "<p>This is an ARN that uniquely identifies a parent (composite) recovery point; for example, \n         <code>arn:aws:backup:us-east-1:123456789012:recovery-point:1EB3B5E7-9EB0-435A-A80B-108B488B0D45</code>.</p>"}))
    DescribeRecoveryPointOutput.add_member(:composite_member_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CompositeMemberIdentifier', traits: {"smithy.api#documentation" => "<p>The identifier of a resource within a composite group, such as \n         nested (child) recovery point belonging to a composite (parent) stack. The \n         ID is transferred from the <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/resources-section-structure.html#resources-section-structure-syntax\">\n            logical ID</a> within a stack.</p>"}))
    DescribeRecoveryPointOutput.add_member(:is_parent, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean2, location_name: 'IsParent', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>This returns the boolean value that a recovery point is a parent (composite) job.</p>"}))
    DescribeRecoveryPointOutput.add_member(:resource_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ResourceName', traits: {"smithy.api#documentation" => "<p>The name of the resource that belongs to the specified backup.</p>"}))
    DescribeRecoveryPointOutput.add_member(:vault_type, Smithy::Schema::Shapes::ShapeRef.new(shape: VaultType, location_name: 'VaultType', traits: {"smithy.api#documentation" => "<p>The type of vault in which the described recovery point is stored.</p>"}))
    DescribeRecoveryPointOutput.add_member(:index_status, Smithy::Schema::Shapes::ShapeRef.new(shape: IndexStatus, location_name: 'IndexStatus', traits: {"smithy.api#documentation" => "<p>This is the current status for the backup index associated with the specified recovery\n         point.</p>\n         <p>Statuses are: <code>PENDING</code> | <code>ACTIVE</code> | <code>FAILED</code> |\n         <code>DELETING</code>\n         </p>\n         <p>A recovery point with an index that has the status of <code>ACTIVE</code> can be\n         included in a search.</p>"}))
    DescribeRecoveryPointOutput.add_member(:index_status_message, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'IndexStatusMessage', traits: {"smithy.api#documentation" => "<p>A string in the form of a detailed message explaining the status of a backup index\n         associated with the recovery point.</p>"}))
    DescribeRecoveryPointOutput.type = Types::DescribeRecoveryPointOutput
