    ListBackupJobSummariesInput.add_member(:account_id, Smithy::Schema::Shapes::ShapeRef.new(shape: AccountId, location_name: 'AccountId', traits: {"smithy.api#documentation" => "<p>Returns the job count for the specified account.</p>\n         <p>If the request is sent from a member account or an account \n         not part of Amazon Web Services Organizations, jobs within requestor's account \n         will be returned.</p>\n         <p>Root, admin, and delegated administrator accounts can use \n         the value ANY to return job counts from every account in the \n         organization.</p>\n         <p>\n            <code>AGGREGATE_ALL</code> aggregates job counts \n         from all accounts within the authenticated organization, \n         then returns the sum.</p>", "smithy.api#httpQuery" => "AccountId"}))
    ListBackupJobSummariesInput.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: BackupJobStatus, location_name: 'State', traits: {"smithy.api#documentation" => "<p>This parameter returns the job count for jobs with the specified state.</p>\n         <p>The the value ANY returns count of all states.</p>\n         <p>\n            <code>AGGREGATE_ALL</code> aggregates job counts for all states and returns the\n         sum.</p>\n         <p>\n            <code>Completed with issues</code> is a status found only in the Backup\n         console. For API, this status refers to jobs with a state of <code>COMPLETED</code> and a\n            <code>MessageCategory</code> with a value other than <code>SUCCESS</code>; that is, the\n         status is completed but comes with a status message. To obtain the job count for\n            <code>Completed with issues</code>, run two GET requests, and subtract the second,\n         smaller number:</p>\n         <p>GET\n         /audit/backup-job-summaries?AggregationPeriod=FOURTEEN_DAYS&State=COMPLETED</p>\n         <p>GET\n         /audit/backup-job-summaries?AggregationPeriod=FOURTEEN_DAYS&MessageCategory=SUCCESS&State=COMPLETED</p>", "smithy.api#httpQuery" => "State"}))
    ListBackupJobSummariesInput.add_member(:resource_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceType, location_name: 'ResourceType', traits: {"smithy.api#documentation" => "<p>Returns the job count for the specified resource type. \n         Use request <code>GetSupportedResourceTypes</code> to obtain \n         strings for supported resource types.</p>\n         <p>The the value ANY returns count of all resource types.</p>\n         <p>\n            <code>AGGREGATE_ALL</code> aggregates job counts \n         for all resource types and returns the sum.</p>\n         <p>The type of Amazon Web Services resource to be backed up; for example, an Amazon Elastic Block Store (Amazon EBS) volume or an Amazon Relational Database Service (Amazon RDS) database.</p>", "smithy.api#httpQuery" => "ResourceType"}))
    ListBackupJobSummariesInput.add_member(:message_category, Smithy::Schema::Shapes::ShapeRef.new(shape: MessageCategory, location_name: 'MessageCategory', traits: {"smithy.api#documentation" => "<p>This parameter returns the job count for the specified \n         message category.</p>\n         <p>Example accepted strings include <code>AccessDenied</code>, \n         <code>Success</code>, and <code>InvalidParameters</code>. See \n         <a href=\"https://docs.aws.amazon.com/aws-backup/latest/devguide/monitoring.html\">Monitoring</a> \n         for a list of accepted MessageCategory strings.</p>\n         <p>The the value ANY returns count of all message categories.</p>\n         <p>\n            <code>AGGREGATE_ALL</code> aggregates job counts \n         for all message categories and returns the sum.</p>", "smithy.api#httpQuery" => "MessageCategory"}))
    ListBackupJobSummariesInput.add_member(:aggregation_period, Smithy::Schema::Shapes::ShapeRef.new(shape: AggregationPeriod, location_name: 'AggregationPeriod', traits: {"smithy.api#documentation" => "<p>The period for the returned results.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>ONE_DAY</code> - The daily job count for the prior 14 days.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SEVEN_DAYS</code> - The aggregated job count for the prior 7 days.</p>\n            </li>\n            <li>\n               <p>\n                  <code>FOURTEEN_DAYS</code> - The aggregated job count for prior 14 days.</p>\n            </li>\n         </ul>", "smithy.api#httpQuery" => "AggregationPeriod"}))
