    RecoveryPointByBackupVault.add_member(:calculated_lifecycle, Smithy::Schema::Shapes::ShapeRef.new(shape: CalculatedLifecycle, location_name: 'CalculatedLifecycle', traits: {"smithy.api#documentation" => "<p>A <code>CalculatedLifecycle</code> object containing <code>DeleteAt</code> and\n            <code>MoveToColdStorageAt</code> timestamps.</p>"}))
    RecoveryPointByBackupVault.add_member(:lifecycle, Smithy::Schema::Shapes::ShapeRef.new(shape: Lifecycle, location_name: 'Lifecycle', traits: {"smithy.api#documentation" => "<p>The lifecycle defines when a protected resource is transitioned to cold storage and when\n         it expires. Backup transitions and expires backups automatically according to\n         the lifecycle that you define. </p>\n         <p>Backups transitioned to cold storage must be stored in cold storage for a minimum of 90\n         days. Therefore, the “retention” setting must be 90 days greater than the “transition to\n         cold after days” setting. The “transition to cold after days” setting cannot be changed\n         after a backup has been transitioned to cold. </p>\n         <p>Resource types that can transition to cold storage are listed in the <a href=\"https://docs.aws.amazon.com/aws-backup/latest/devguide/backup-feature-availability.html#features-by-resource\">Feature \n         availability by resource</a> table. Backup ignores this expression for\n         other resource types.</p>"}))
