    StartBackupJobOutput.add_member(:recovery_point_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ARN, location_name: 'RecoveryPointArn', traits: {"smithy.api#documentation" => "<p>\n            <i>Note: This field is only returned for Amazon EFS and Advanced DynamoDB \n         resources.</i>\n         </p>\n         <p>An ARN that uniquely identifies a recovery point; for example,\n            <code>arn:aws:backup:us-east-1:123456789012:recovery-point:1EB3B5E7-9EB0-435A-A80B-108B488B0D45</code>.</p>"}))
